    if (match) visibleCount++;
  });

  // si aucune carte n'est visible → afficher le message
  document.getElementById("noResults").style.display =
    visibleCount === 0 ? "block" : "none";
}


  // lit les data-attributes du bouton: data-name et data-content (base64),
