  function downloadFromData(btn) {
    try {
      const name = btn.getAttribute('data-name') || 'signature';
      const b64 = btn.getAttribute('data-content') || '';
      // atob décode base64 vers chaine UTF-8 byte seq ; on convertit correctement en UTF-8:
      // méthode simple: decode via atob puis construire string avec percent-encoding
      const binaryStr = atob(b64);
      // convertir binaryStr (latin1) en UTF-8 string
      let utf8str = decodeURIComponent(Array.prototype.map.call(binaryStr, function(c){
        return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2);
      }).join(''));
      downloadHTML(name, utf8str);
    } catch (e) {
      alert('Erreur lors du téléchargement : ' + e.message);
      console.error(e);
    }
  }
</script>
